     1|/**
     2| * Focused deploy: upload the investor-first home feed landing files
     3| * (index.html + new ivx-home-feed.js + ivx-reels.js) to the ivxholding.com
     4| * S3 bucket and invalidate CloudFront. Mirrors deploy-landing.mjs placeholder
     5| * replacement exactly.
     6| *
     7| * Usage: node scripts/deploy-home-feed.mjs   (from expo/, reads ./.env)
     8| */
     9|import { S3Client, PutObjectCommand } from '@aws-sdk/client-s3';
    10|import { CloudFrontClient, ListDistributionsCommand, CreateInvalidationCommand } from '@aws-sdk/client-cloudfront';
    11|import { readFileSync } from 'fs';
    12|
    13|/* ---- load env from ./.env (line-by-line, tolerates polluted lines) ---- */
    14|const envText = readFileSync('./.env', 'utf-8');
    15|const env = {};
    16|for (const line of envText.split('\n')) {
    17|  const m = line.match(/^([A-Z0-9_]+)=(.*)$/);
    18|  if (m) env[m[1]] = m[2].trim().replace(/^["']|["']$/g, '');
    19|}
    20|const ACCESS_KEY = env.AWS_ACCESS_KEY_ID || process.env.AWS_ACCESS_KEY_ID || '';
    21|const SECRET_KEY = env.AWS_SECRET_ACCESS_KEY || process.env.AWS_SECRET_ACCESS_KEY || '';
    22|const REGION = env.AWS_REGION || 'us-east-1';
    23|if (!ACCESS_KEY || !SECRET_KEY) {
    24|  console.error('Missing AWS credentials');
    25|  process.exit(1);
    26|}
    27|
    28|const BUCKET = 'ivxholding.com';
    29|const s3 = new S3Client({ region: REGION, credentials: { accessKeyId: ACCESS_KEY, secretAccessKey: SECRET_KEY } });
    30|
    31|const backendUrl = 'https://api.ivxholding.com';
    32|
    33|/* ---- index.html: same placeholder replacement as deploy-landing.mjs ---- */
    34|let indexHtml = readFileSync('./ivxholding-landing/index.html', 'utf-8');
    35|indexHtml = indexHtml.replace(/__IVX_BACKEND_URL__/g, backendUrl);
    36|indexHtml = indexHtml.replace(/__IVX_API_URL__/g, 'https://ivxholding.com');
    37|
    38|console.log('Uploading index.html ...');
    39|await s3.send(new PutObjectCommand({
    40|  Bucket: BUCKET,
    41|  Key: 'index.html',
    42|  Body: indexHtml,
    43|  ContentType: 'text/html; charset=utf-8',
    44|  CacheControl: 'no-cache, no-store, must-revalidate',
    45|}));
    46|console.log('index.html uploaded');
    47|
    48|/* ---- JS assets ---- */
    49|for (const key of ['ivx-home-feed.js', 'ivx-reels.js']) {
    50|  const body = readFileSync(`./ivxholding-landing/${key}`, 'utf-8');
    51|  console.log(`Uploading ${key} ...`);
    52|  await s3.send(new PutObjectCommand({
    53|    Bucket: BUCKET,
    54|    Key: key,
    55|    Body: body,
    56|    ContentType: 'application/javascript; charset=utf-8',
    57|    CacheControl: 'public, max-age=300',
    58|  }));
    59|  console.log(`${key} uploaded`);
    60|}
    61|
    62|/* ---- CloudFront invalidation ---- */
    63|try {
    64|  const cf = new CloudFrontClient({ region: 'us-east-1', credentials: { accessKeyId: ACCESS_KEY, secretAccessKey: SECRET_KEY } });
    65|  const resp = await cf.send(new ListDistributionsCommand({}));
    66|  const dist = (resp.DistributionList?.Items || []).find((d) =>
    67|    (d.Aliases?.Items || []).some((a) => a === 'ivxholding.com' || a === 'www.ivxholding.com'));
    68|  if (dist) {
    69|    const inv = await cf.send(new CreateInvalidationCommand({
    70|      DistributionId: dist.Id,
    71|      InvalidationBatch: {
    72|        CallerReference: `home-feed-${Date.now()}`,
    73|        Paths: { Quantity: 4, Items: ['/', '/index.html', '/ivx-home-feed.js', '/ivx-reels.js'] },
    74|      },
    75|    }));
    76|    console.log('CloudFront invalidation triggered on', dist.Id, '→', inv.Invalidation?.Id);
    77|  } else {
    78|    console.log('No CloudFront distribution found — S3 direct');
    79|  }
    80|} catch (e) {
    81|  console.warn('CloudFront invalidation skipped:', e.message);
    82|}
    83|console.log('DONE');

